    [TestMethod]
    public void TestPlayerMovesHomeAndIsCompletelyHealedOnKill()
    {
        GameSession gameSession = new GameSession(new Player("Jakob", "Warrior", currentHitPoints: 100, health: 100, experience: 0, gold: 1000000));
        gameSession.CurrentPlayer.TakeDamage(999);
        Assert.AreEqual("Home", gameSession.CurrentLocation.Name);
